    "description": "The Envision team performed interior and exterior renovations to enhance the worship experience of congregants at Mount Olive. The 12,000 SF Polk County worship center was upgraded with new flooring, expansions to the churchfront and stage, rooms and bathroom renovations, a new foyer, a complete remodel of the sanctuary, a new and modern lighting system, and a conversion of upstairs rooms into a multipurpose space. ",
