    "title": "5000 Acline Drive Office Build Out",
    "slug": "5000-acline-drive-office-build-out",
    "completed": "2024-11-01",
    "location": "Tampa, FL",
    "area": "4,500 SF",
    "createdAt": "2026-02-13T04:25:08.719Z",
    "updatedAt": "2026-06-17T16:21:04.843Z",
    "publishedAt": "2026-06-17T16:21:04.961Z",
    "description": "The 5000 Acline Drive Office Build Out was designed with many factors in mind, including potential for future growth, the flow of the office, aesthetic of the interior space, and provision of a welcoming feel. Built from shell space, the project resulted in seven offices, a “cubicle” work area with three work spaces, one large conference room, one small conference room, two restrooms, and a break room with a kitchenette at a total of 4,500 SF. ",
