    "title": "Florida Aquarium Restroom Renovation",
    "slug": "florida-aquarium-restroom-renovation",
    "completed": "2022-12-01",
    "location": "Tampa, FL",
    "area": null,
    "createdAt": "2026-06-08T02:55:46.410Z",
    "updatedAt": "2026-06-08T03:06:39.833Z",
    "publishedAt": "2026-06-08T03:06:39.890Z",
    "description": "The Florida Aquarium Restroom Renovation involved significant interior upgrades to the four main restrooms at their Tampa facility. Reflecting the aquarium’s commitment to quality, the upgraded restrooms feature new epoxy floors, ceiling paint, urinals, fixtures, countertops, can lights, moisture-resistant gypsum boards, LED backlit mirrors, wall-mounted fixtures and automatic sensors, and lavatories with automatic faucets and soap dispensers.",
